<?php
namespace App\Features\Vehicles\Controllers;
use App\Features\Vehicles\Requests\BulkVehicleRequest; use App\Features\Vehicles\Requests\VehicleRequest; use App\Features\Vehicles\Repositories\VehicleRepository; use App\Features\Vehicles\Repositories\VehicleTimelineRepository; use App\Features\Vehicles\Services\VehicleService; use Illuminate\Http\Request; use Symfony\Component\HttpFoundation\StreamedResponse;
class VehicleController { public function __construct(private VehicleRepository $vehicles, private VehicleService $service, private VehicleTimelineRepository $timeline) {} public function index(Request $r){ $this->authorize($r,'vehicle.view'); return response()->json(['success'=>true,'data'=>$this->vehicles->paginate($r->query(),$this->tenant($r))]); } public function store(VehicleRequest $r){ return response()->json(['success'=>true,'data'=>$this->service->create($r->validated(),$this->tenant($r),$r->user()?->id)],201); } public function show(Request $r,string $id){ $this->authorize($r,'vehicle.view'); return response()->json(['success'=>true,'data'=>$this->vehicles->find($id,$this->tenant($r))]); } public function update(VehicleRequest $r,string $id){ $v=$this->vehicles->find($id,$this->tenant($r)); return response()->json(['success'=>true,'data'=>$this->service->update($v,$r->validated(),$r->user()?->id)]); } public function destroy(Request $r,string $id){ $this->authorize($r,'vehicle.delete'); $this->service->bulkDelete([$id],$this->tenant($r)); return response()->json(['success'=>true,'data'=>null]); } public function bulkDelete(BulkVehicleRequest $r){ return response()->json(['success'=>true,'data'=>['deleted'=>$this->service->bulkDelete($r->validated('ids'),$this->tenant($r))]]); } public function bulkUpdate(BulkVehicleRequest $r){ return response()->json(['success'=>true,'data'=>['updated'=>$this->service->bulkUpdate($r->validated('ids'),$this->tenant($r),$r->validated('updates',[]),$r->user()?->id)]]); } public function timeline(Request $r,string $id){ $this->authorize($r,'vehicle.view'); return response()->json(['success'=>true,'data'=>$this->timeline->list($id,$this->tenant($r))]); } public function export(Request $r): StreamedResponse { $this->authorize($r,'vehicle.export'); $rows=$this->vehicles->exportQuery($r->query(),$this->tenant($r)); if($r->query('format')==='pdf') return response()->streamDownload(function() use($rows){ echo '<html><body><h1>Vehicles</h1><table border="1" cellpadding="6"><tr><th>Vehicle Number</th><th>Owner</th><th>Mobile</th><th>Type</th><th>Manufacturer</th><th>Model</th><th>Fuel</th><th>Insurance</th><th>Fitness</th><th>Permit</th><th>Tax</th><th>PUC</th></tr>'; foreach($rows as $v){ echo '<tr><td>'.e($v->vehicle_number).'</td><td>'.e(trim(($v->customer->first_name??'').' '.($v->customer->last_name??''))).'</td><td>'.e($v->customer->mobile??'').'</td><td>'.e($v->vehicle_type).'</td><td>'.e($v->manufacturer).'</td><td>'.e($v->model).'</td><td>'.e($v->fuel_type).'</td><td>'.e($v->insurance_status).'</td><td>'.e($v->fitness_status).'</td><td>'.e($v->permit_status).'</td><td>'.e($v->tax_status).'</td><td>'.e($v->puc_status).'</td></tr>'; } echo '</table><script>window.print()</script></body></html>'; },'vehicles.pdf',['Content-Type'=>'application/pdf']); return response()->streamDownload(function() use($rows){ $out=fopen('php://output','w'); fputcsv($out,['Vehicle Number','Owner Name','Mobile Number','Vehicle Type','Manufacturer','Model','Fuel','Insurance Status','Fitness Status','Permit Status','Tax Status','PUC Status']); foreach($rows as $v) fputcsv($out,[$v->vehicle_number,trim(($v->customer->first_name??'').' '.($v->customer->last_name??'')),$v->customer->mobile??'',$v->vehicle_type,$v->manufacturer,$v->model,$v->fuel_type,$v->insurance_status,$v->fitness_status,$v->permit_status,$v->tax_status,$v->puc_status]); },'vehicles.csv'); } private function tenant(Request $r): string { return (string)($r->user()?->tenant_id ?? $r->header('X-Tenant-Id')); } private function authorize(Request $r,string $permission): void { abort_unless($r->user()?->can($permission),403); } }
